python3 - <<'EOF'
import re,os,collections
def path(m):
    return m.replace('.','/')+'.lean'
def imports(f):
    if not os.path.exists(f): return []
    out=[]
    for line in open(f,encoding='utf8'):
        line=line.strip()
        if line.startswith('import '):
            n=line.split()[1]
            if n.startswith('AlgebraicJacobian'): out.append(n)
        elif line and not line.startswith('/-') and not line.startswith('--') and not line.startswith('-'):
            pass
    return out
seen=set(); stack=['AlgebraicJacobian']
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for i in imports(path(m)): stack.append(i)
print("cone size (incl root):",len(seen))
allm=set()
for r,d,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            allm.add(os.path.join(r,f)[:-5].replace('/','.'))
allm.add('AlgebraicJacobian')
print("total modules:",len(allm))
un=sorted(allm-seen)
print("unrooted count:",len(un))
led=[m for m in un if '.Ledger.' in m]
print("unrooted Ledger:",len(led))
for m in led: print("   ",m)
for t in ['AlgebraicJacobian.RiemannRoch.Ledger.SectionsFieldBaseChange','AlgebraicJacobian.RiemannRoch.Ledger.GenusFieldInvariance','AlgebraicJacobian.RiemannRoch.CohomologyKit','AlgebraicJacobian.RiemannRoch.CurveBaseChange','AlgebraicJacobian.RiemannRoch.Ledger.ExtensionUniformity']:
    print(("ROOTED  " if t in seen else "UNROOTED"),t)
